    pageIds.forEach(id => selectedIds.add(id));
  } else {
    pageIds.forEach(id => selectedIds.delete(id));
  }
  refreshUI();
}

function onRowCheck(e) {
  const id = Number(e.target.dataset.id);
  if (e.target.checked) {
    selectedIds.add(id);
  } else {
    selectedIds.delete(id);
