    sortDir = sortDir === 'asc' ? 'desc' : 'asc';
  } else {
    sortKey = key;
    sortDir = 'asc';
  }
  currentPage = 1;
  refreshUI();
}

function goTo(page) {
  var tp = totalPages();
  if (page < 1 || page > tp) return;
  currentPage = page;
  refreshUI();
}

function onSelectAll(e) {
  var pageIds = getPageData().map(function(r) { return r.id; });
  if (e.target.checked) {
    pageIds.forEach(function(id) { selectedIds.add(id); });
  } else {
    pageIds.forEach(function(id) { selectedIds.delete(id); });
  }
  refreshUI();
}

function onRowCheck(e) {
  var id = Number(e.target.dataset.id);
  if (e.target.checked) { selectedIds.add(id); }
  else                  { selectedIds.delete(id); }

  var pageIds = getPageData().map(function(r) { return r.id; });
  var sa = document.getElementById('selectAll');
  if (sa) sa.checked = pageIds.every(function(id) { return selectedIds.has(id); });

  updateSelectedCount();
  var tr = e.target.closest('tr');
  if (tr) tr.classList.toggle('selected', e.target.checked);

  console.log('\\u0412\\u044B\\u0431\\u0440\\u0430\\u043D\\u043D\\u044B\\u0435 ID:', Array.from(selectedIds).sort(function(a,b){ return a-b; }));
}

pageSizeSel.addEventListener('change', function() {
  pageSize = Number(pageSizeSel.value);
  currentPage = 1;
  refreshUI();
});

refreshUI();
</script>
